// StatusString returns a mnemonic for the documented status codes, otherwise the
// hex value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "ERROR_SUCCESS"
	case ErrorFileNotFound:
		return "ERROR_FILE_NOT_FOUND"
	case ErrorPathNotFound:
		return "ERROR_PATH_NOT_FOUND"
	case ErrorAccessDenied:
		return "ERROR_ACCESS_DENIED"
	case ErrorInvalidHandle:
		return "ERROR_INVALID_HANDLE"
	case ErrorInvalidData:
		return "ERROR_INVALID_DATA"
	case ErrorInvalidParameter:
		return "ERROR_INVALID_PARAMETER"
	case ErrorInsufficientBuffer:
		return "ERROR_INSUFFICIENT_BUFFER"
	case ErrorInvalidName:
		return "ERROR_INVALID_NAME"
	case ErrorInvalidLevel:
		return "ERROR_INVALID_LEVEL"
	case ErrorMoreData:
		return "ERROR_MORE_DATA"
	case ErrorDependentServicesRunning:
		return "ERROR_DEPENDENT_SERVICES_RUNNING"
	case ErrorInvalidServiceControl:
		return "ERROR_INVALID_SERVICE_CONTROL"
	case ErrorServiceRequestTimeout:
		return "ERROR_SERVICE_REQUEST_TIMEOUT"
	case ErrorServiceNoThread:
		return "ERROR_SERVICE_NO_THREAD"
	case ErrorServiceDatabaseLocked:
		return "ERROR_SERVICE_DATABASE_LOCKED"
	case ErrorServiceAlreadyRunning:
		return "ERROR_SERVICE_ALREADY_RUNNING"
	case ErrorInvalidServiceAccount:
		return "ERROR_INVALID_SERVICE_ACCOUNT"
	case ErrorServiceDisabled:
		return "ERROR_SERVICE_DISABLED"
	case ErrorCircularDependency:
		return "ERROR_CIRCULAR_DEPENDENCY"
	case ErrorServiceDoesNotExist:
		return "ERROR_SERVICE_DOES_NOT_EXIST"
	case ErrorServiceCannotAcceptCtrl:
		return "ERROR_SERVICE_CANNOT_ACCEPT_CTRL"
	case ErrorServiceNotActive:
		return "ERROR_SERVICE_NOT_ACTIVE"
	case ErrorDatabaseDoesNotExist:
		return "ERROR_DATABASE_DOES_NOT_EXIST"
	case ErrorServiceDependencyFail:
		return "ERROR_SERVICE_DEPENDENCY_FAIL"
	case ErrorServiceLogonFailed:
		return "ERROR_SERVICE_LOGON_FAILED"
	case ErrorServiceMarkedForDelete:
		return "ERROR_SERVICE_MARKED_FOR_DELETE"
	case ErrorServiceExists:
		return "ERROR_SERVICE_EXISTS"
	case ErrorServiceDependencyDeleted:
		return "ERROR_SERVICE_DEPENDENCY_DELETED"
	case ErrorDuplicateServiceName:
		return "ERROR_DUPLICATE_SERVICE_NAME"
	case ErrorShutdownInProgress:
		return "ERROR_SHUTDOWN_IN_PROGRESS"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

